"""
Unit and Integration Tests for RealSentinel2Dataset, Manifest Handling, and Normalization.
Validates Step 3 of Module 3 merge preparation.
"""

import os
import json
import tempfile
import pytest
import numpy as np
import pandas as pd
import torch

from config.constants import NUM_BANDS, NUM_CLASSES, TILE_SIZE
from data.datasets import (
    MockSentinel2Dataset,
    RealSentinel2Dataset,
    partition_manifest,
)


@pytest.fixture(scope="module")
def fake_dataset_dir():
    """Returns path to fake dataset generated by tools/make_fake_dataset.py."""
    data_dir = "data/fake_dataset"
    if not os.path.exists(os.path.join(data_dir, "manifest.csv")):
        from tools.make_fake_dataset import generate_fake_dataset
        generate_fake_dataset(output_dir=data_dir, num_samples=20)
    return data_dir


def test_mock_dataset():
    """Verify MockSentinel2Dataset yields exact dimensions and valid labels."""
    ds = MockSentinel2Dataset(num_samples=10, channels=NUM_BANDS, height=TILE_SIZE, width=TILE_SIZE)
    assert len(ds) == 10
    x, y = ds[0]
    assert x.shape == (NUM_BANDS, TILE_SIZE, TILE_SIZE)
    assert x.dtype == torch.float32
    assert y.dtype == torch.int64
    assert 0 <= y.item() < NUM_CLASSES


def test_real_dataset_npy_and_tif(fake_dataset_dir):
    """Verify RealSentinel2Dataset loads both .npy and .tif tiles with correct shape and range."""
    manifest_path = os.path.join(fake_dataset_dir, "manifest.csv")
    df = pd.read_csv(manifest_path)
    ds = RealSentinel2Dataset(manifest_df=df, data_dir=fake_dataset_dir)

    assert len(ds) == len(df)
    # Check first tile (.npy)
    x0, y0 = ds[0]
    assert x0.shape == (NUM_BANDS, TILE_SIZE, TILE_SIZE)
    assert x0.dtype == torch.float32
    assert 0.0 <= x0.min().item() <= x0.max().item() <= 1.0
    assert 0 <= y0.item() < NUM_CLASSES

    # Check last tile (.tif)
    x_last, y_last = ds[len(ds) - 1]
    assert x_last.shape == (NUM_BANDS, TILE_SIZE, TILE_SIZE)
    assert x_last.dtype == torch.float32
    assert 0.0 <= x_last.min().item() <= x_last.max().item() <= 1.0


def test_channel_order_auto_detection():
    """Verify channel-first (13, H, W) and channel-last (H, W, 13) both resolve to (13, 256, 256)."""
    with tempfile.TemporaryDirectory() as tmpdir:
        # Channel first
        p_first = os.path.join(tmpdir, "first.npy")
        np.save(p_first, np.random.rand(13, 64, 64).astype(np.float32))

        # Channel last
        p_last = os.path.join(tmpdir, "last.npy")
        np.save(p_last, np.random.rand(64, 64, 13).astype(np.float32))

        df = pd.DataFrame([
            {"tile_path": p_first, "label": 0},
            {"tile_path": p_last, "label": 1},
        ])
        ds = RealSentinel2Dataset(manifest_df=df, target_size=256)

        x0, _ = ds[0]
        x1, _ = ds[1]
        assert x0.shape == (13, 256, 256)
        assert x1.shape == (13, 256, 256)


def test_invalid_band_count_raises():
    """Verify tiles without exactly 13 bands raise clear ValueError."""
    with tempfile.TemporaryDirectory() as tmpdir:
        bad_tile = os.path.join(tmpdir, "bad.npy")
        np.save(bad_tile, np.random.rand(10, 64, 64).astype(np.float32))

        df = pd.DataFrame([{"tile_path": bad_tile, "label": 0}])
        ds = RealSentinel2Dataset(manifest_df=df)

        with pytest.raises(ValueError, match="Expected 13 bands"):
            _ = ds[0]


def test_label_map_and_unknown_label(fake_dataset_dir):
    """Verify label_map handles mapping and unknown labels raise KeyError."""
    label_map = {"Forest": 1, "Water": 8}
    df = pd.DataFrame([
        {"tile_path": "tiles_npy/tile_000.npy", "label": "Forest"},
        {"tile_path": "tiles_npy/tile_000.npy", "label": "UnknownLand"},
    ])
    ds = RealSentinel2Dataset(manifest_df=df, data_dir=fake_dataset_dir, label_map=label_map)

    # Valid mapped label
    _, y0 = ds[0]
    assert y0.item() == 1

    # Unknown label raises KeyError
    with pytest.raises(KeyError, match="Unknown label 'UnknownLand'"):
        _ = ds[1]


def test_partition_manifest(fake_dataset_dir):
    """Verify partitioning handles train/val/test splits and saves splits.json."""
    manifest_path = os.path.join(fake_dataset_dir, "manifest.csv")
    df = pd.read_csv(manifest_path)

    with tempfile.TemporaryDirectory() as tmpdir:
        splits_json = os.path.join(tmpdir, "splits.json")
        train_df, val_df, test_df = partition_manifest(
            df, val_ratio=0.2, test_ratio=0.2, seed=42, splits_output_path=splits_json
        )
        assert len(train_df) + len(val_df) + len(test_df) == len(df)
        assert os.path.exists(splits_json)
        with open(splits_json, "r", encoding="utf-8") as f:
            meta = json.load(f)
        assert "train_paths" in meta
        assert meta["train_count"] == len(train_df)
